mapper.insert:
INSERT INTO group_join_request (
    group_id, user_key, status, requested_at
) VALUES (
    #{groupId}, #{userKey}, 'PENDING', NOW()
)

mapper.select:
SELECT request_id, group_id, user_key, status, requested_at, approved_at, reject_reason
FROM group_join_request
WHERE user_key = #{userKey}
AND group_id = #{groupId}
ORDER BY requested_at DESC

SELECT r.request_id, r.group_id, r.user_key, u.nickname, g.name AS groupName, r.status, r.requested_at, r.approved_at, r.reject_reason FROM group_join_request r JOIN `user` u ON u.user_key = r.user_key JOIN `group` g ON g.group_id = r.group_id WHERE r.status = 'PENDING'
AND (u.nickname LIKE CONCAT('%', #{q}, '%') OR g.name LIKE CONCAT('%', #{q}, '%'))
AND r.requested_at >= #{from}
AND r.requested_at < DATE_ADD(#{to}, INTERVAL 1 DAY)
ORDER BY r.requested_at ASC LIMIT #{limit} OFFSET #{offset}

SELECT request_id, group_id, user_key, status, requested_at, approved_at, reject_reason
FROM group_join_request
WHERE request_id = #{requestId}

mapper.update:
UPDATE group_join_request
SET status='APPROVED', approved_at = NOW(), updated_by = #{processedBy}
WHERE request_id = #{requestId}
AND status = 'PENDING'

UPDATE group_join_request
SET status='REJECTED', reject_reason = #{rejectReason}, updated_by = #{processedBy}
WHERE request_id = #{requestId}
AND status = 'PENDING'

UPDATE group_join_request
SET status='CANCELLED'
WHERE request_id = #{requestId}
AND user_key = #{userKey}
AND status = 'PENDING'
